// GENERATED by scripts/sync-shared.mjs from src/mystery — do not edit here.
// Per-case worlds — game-designer owned. Pure data (shared with Deno Edge Functions): no Math.random, no Date, no DOM.
// Rationale, ASCII sketches, tables and pacing math: docs/MYSTERY_DESIGN.md §10 (overhaul), §11 (Crackstone) and §12
// (final 2026-10-24: compact play areas, cabinets, Slurp, encounter-director spawns).
//
// FINAL (compact maps): every case now plays inside its own fenced `playArea` (55–70 m per side) cut out of the shared
// Raven Island (island.ts). The area always contains Iago Tower (8, −51.5) and its door (8, −46). Boundary walls are
// case extraWalls (`*_bnd_*`, plus door plugs `*_rubble_*`); island walls / cover outside the bounds are irrelevant.
//   01 Poisoned Archive  x −19..45, z −60..9   archive (north half of the research room) + stacks + porter's lodge +
//                                               greenhouse + Poison Garden + Tower Yard
//   02 Crypt's Witness   x −45..19.5, z −60..9 crypt hall + catacombs + crypt side path + ravine terrace +
//                                               maintenance tunnel (rock ring in the west courtyard) + tower
//   03 Midnight Signal   x −19..45, z −60..−5  ravine guard post + control hut + potting shed + old kennel +
//                                               watchtower yard + Restricted Yard (fence + checkpoint gate)
//
// Invariants (checked by hand against island.ts — no shell this pass; see design doc §12.7):
// - Priors of every clue group, the egg sites and every enemy's spawn weights each sum to 1.
// - Every candidate site lies in the RoomId it declares (first match in island.ts ROOMS order), ≥ 1.5 m from every wall
//   surface and ≥ 0.3 m from every cover surface; all sites of one case are ≥ 3 m apart.
// - Every new wall either JOINS another wall (clear gap < 0.8 m) or leaves ≥ 3 m (doorway) / ≥ 2.5 m (side-by-side
//   corridor) to every island and case wall — the caseIslands.test.ts rule, applied to the walls outside the bounds too.
// - Hyde patrol loops: every leg (incl. last → first) keeps ≥ 0.6 m + radius from every wall and cover piece.
// - Hyde spawns ≥ 25 m from the case's playerStart; Crackstone / Slurp spawns ≥ 20 m; all ≥ 1.5 m from walls / cover.
// - Cabinets: radius 0.6, revealM 1.2, back to a wall, door (doorYaw) facing ≥ 1.6 m of open floor; ≥ 3.5 m from any
//   clue / egg site, examine or lever (no E-prompt overlap); ≥ 2.2 m from Crackstone waypoints / Slurp wander points.
// - Zones tile the playArea bounds exactly (no gap, no overlap except shared edges).
// - Crackstone (enemy contract): haunt centres ≥ 1.2 m from wall surfaces / cover edges on every waypoint and leg.
//
// Id conventions for the renderer: prefix pa_ = Case 01, cw_ = Case 02, ms_ = Case 03. Wall ids containing `shelf`,
// `stack`, `rec`, `bookcase` = bookshelves; `vine` = vine hedges; `rubble` / `tunnel` = collapsed rock; `fence` / `gate`
// = security fence; `hut` = guard-hut walls. Hiding spots with kind 'cabinet' are `*_cab_*`.
import type {
  CaseId, CaseWorldDef, CoverDef, EncounterSpawnDef, EnemyId, ExamineDef, HazardDef, HidingSpotDef, HydeSpawnDef, Vec2,
  WallDef, ZoneDef,
} from '../types.ts';

/** Axis-aligned rectangle, counter-clockwise seen from above (NW → SW → SE → NE) — same convention as island.ts. */
const rect = (minX: number, minZ: number, maxX: number, maxZ: number): Vec2[] => [
  { x: minX, z: minZ }, { x: minX, z: maxZ }, { x: maxX, z: maxZ }, { x: maxX, z: minZ },
];

/** Yaw that faces from a toward b (repo convention: yaw 0 faces −Z, forward = (−sin, −cos)). */
const faceToward = (ax: number, az: number, bx: number, bz: number): number => Math.atan2(-(bx - ax), -(bz - az));

/** Door yaws for cabinets: the direction the door faces (= where the player steps out). */
const FACE_NORTH = 0; // −Z
const FACE_SOUTH = Math.PI; // +Z
const FACE_WEST = Math.PI / 2; // −X
const FACE_EAST = -Math.PI / 2; // +X

function wall(id: string, ax: number, az: number, bx: number, bz: number, thickness: number, height: number, kind: WallDef['kind']): WallDef {
  return { id, a: { x: ax, z: az }, b: { x: bx, z: bz }, thickness, height, kind };
}

function cover(id: string, x: number, z: number, radius: number, height: CoverDef['height'], kind: CoverDef['kind']): CoverDef {
  return { id, x, z, radius, height, kind };
}

function hide(id: string, x: number, z: number, radius: number, revealM: number, kind: HidingSpotDef['kind']): HidingSpotDef {
  return { id, x, z, radius, revealM, kind };
}

/** An enterable hiding cabinet (FINAL_CONTRACT §6): radius 0.6, reveal 1.2 m while the door is open. */
function cabinet(id: string, x: number, z: number, doorYaw: number): HidingSpotDef {
  return { id, x, z, radius: 0.6, revealM: 1.2, kind: 'cabinet', doorYaw };
}

/** Zone rectangles of one case (they tile its playArea bounds). */
function zones(list: readonly (readonly [string, string, number, number, number, number])[]): ZoneDef[] {
  return list.map(([id, name, minX, minZ, maxX, maxZ]) => ({ id, name, polygon: rect(minX, minZ, maxX, maxZ) }));
}

/** A weighted encounter spawn (director). */
function spawn(enemy: EnemyId, id: string, name: string, zoneId: string, x: number, z: number, yaw: number, weight: number): EncounterSpawnDef {
  return { id, enemy, name, zoneId, x, z, yaw, weight };
}

/** The legacy Hyde spawn list = the director's Hyde spawns (same ids, points, weights). */
function hydeSpawnsOf(spawns: readonly EncounterSpawnDef[]): HydeSpawnDef[] {
  return spawns.filter((s) => s.enemy === 'hyde').map(({ id, name, zoneId, x, z, yaw, weight }) => ({ id, name, zoneId, x, z, yaw, weight }));
}

